import {advanceChapter04,assignCausalIntro,assignComparison,assignConflictType,assignConsequence,assignEscalation,assignFinalRelation,assignGeneralEpistemic,assignHistory,assignInternalPreparation,assignJuliet,assignJulietAlternative,assignKnowledge,assignSituation,chooseGoal,chooseNeutralTurning,chooseTurningPoint,compareConflicts,completeChapter04,distinguishDecision,explainTurningPoint,initialChapter04Session,linkGoal,placeChainEvent,placeMonologueStep,saveIntroGoals,selectIntroFact,setChainRelation,setCurveOrder,setFinalCurve,setFinalEvidence,setFinalEvidenceAnalysis,setFinalMeaning,setFinalTransfer,setIncompatibility,solveGeneralEvidence,solveGeneralGoal,solveNeutralActionChain,solveTombActionChain,type Chapter04Session} from "../mechanics/chapter_04_engine";

type Props={gameState:GameState;onSave:(s:Chapter04Session)=>void;onExit:()=>void;onComplete:(s:Chapter04Session)=>void};
type Result={valid:boolean;session:Chapter04Session};
type FailureDetails={incorrectItems:string[];resolution:string[]};
const labels:Record<string,string>={situation:"Ausgangslage",conflict_and_goals:"Zielkonflikt",result:"Folge",prior:"Vorgeschichte",current:"Gegenwärtige Ausgangslage",history:"Vorgeschichte",knowledge:"Wissensstand",future:"Vermutete Zukunft",irrelevant:"Irrelevante Information",not_determinable:"Nicht ausreichend belegt",romeo_knowledge:"Romeo: Wissensstand",romeo_intention:"Romeo: Absicht",paris_knowledge:"Paris: Wissensstand",paris_interpretation:"Paris: Deutung",paris_intention:"Paris: Absicht",unsupported:"Nicht ausreichend belegt",intention:"Absicht",interpretation:"Deutung",external:"Äußerer Konflikt",internal:"Innerer Konflikt",tension:"Anspannung",escalation:"Zuspitzung",turning:"Wendepunkt",immediate:"Unmittelbare Folge",farther:"Weitere Folge",wish:"Handlungswunsch",fear:"Befürchtung / Gegenkraft",weighing:"Abwägung",decision:"Entscheidung",execution:"Ausführung",supports_action:"Spricht für das Handeln",feared_possibility:"Befürchtete Möglichkeit",textual:"Textlich erwogen",plausible:"Situativ plausibel",causes:"Verursacht",contributes:"Trägt bei",only_later:"Nur später / kein belegter Zusammenhang"};
const chapter04Tasks=["","Wählen Sie alle konfliktbestimmenden Informationen, bestimmen Sie die gegensätzlichen Ziele und erschließen Sie die verbleibenden Ziele aus dem Verhalten.","Ordnen Sie jeden Gegensatz als äußeren oder inneren Konflikt ein und unterscheiden Sie anschließend Vorgeschichte, Gegenwart, Wissen, Zukunft und Irrelevantes.","Ordnen Sie jede Ereignisbeziehung als Ursache, beitragende Bedingung oder bloßes Später ein.","Trennen Sie Wissensstand, Absicht und Deutung; verbinden Sie danach Behauptung, passenden Beleg und Analyse.","Bringen Sie alle Ereignisse in die Reihenfolge von Ausgangslage bis Folge und prüfen Sie anschließend ihre Verlaufsfunktion.","Bilden Sie für jede Aufgabe eine vollständige Kette aus Handlung, unmittelbarer Reaktion und Folge.","Wählen Sie einen möglichen Wendepunkt und begründen Sie Ihr Urteil mit Davor, Veränderung und Danach.","Ordnen Sie alle Angaben zur Gruft als Ausgangslage, Vorgeschichte oder nicht feststellbar ein.","Ordnen Sie jede Aussage dem Wissensstand, der Absicht oder Deutung von Romeo oder Paris zu; unbelegte Aussagen kennzeichnen Sie entsprechend.","Bestimmen Sie für beide Figuren Ziel, Primärtextbeleg und Analyse und erklären Sie danach den Zielkonflikt.","Bringen Sie die fünf Stationen der Gruftszene in ihre belegte Handlungsreihenfolge.","Beurteilen Sie für jede Verbindung, ob sie unmittelbar verursacht, nur beiträgt oder lediglich später folgt.","Bilden Sie aus jeder Äußerung die passende Kette von Handlung, Reaktion und Veränderung.","Ordnen Sie Anspannung, Zuspitzung und Wendepunkt, begründen Sie den Umschlag und unterscheiden Sie unmittelbare, weitere und unbelegte Folgen.","Ordnen Sie jede Aussage als Wunsch, Befürchtung, Abwägung, Entscheidung oder Ausführung ein.","Lesen Sie Juliettes Monolog und starten Sie anschließend die Untersuchung ihres inneren Konflikts.","Ordnen Sie alle Textinformationen eindeutig der Situation, einer Handlungskraft, einer befürchteten Möglichkeit, der Entscheidung oder der Ausführung zu.","Bringen Sie die Phasen von Juliettes Abwägung in die textlich belegte Reihenfolge.","Wählen Sie die Zuordnung, die Entschluss in der Figurenrede und körperlichen Vollzug in der Bühnenanweisung trennt.","Ordnen Sie jede Alternative als textlich erwogen, situativ plausibel oder nicht ausreichend belegt ein.","Vergleichen Sie äußeren und inneren Konflikt nach Trägern und Verlauf und wählen Sie anschließend eine textnahe Synthese.","Rekonstruieren Sie den Handlungsverlauf, prüfen Sie die Kausalbeziehungen und verbinden Sie Deutung, Textbeleg, Analyse und Transfer vollständig."];
const chapter04SecondHints:Record<number,string>={
  2:"Ein äußerer Konflikt liegt zwischen Konfliktträgern; ein innerer zwischen widerstreitenden Kräften derselben Figur.",
  3:"Zeitliche Reihenfolge allein beweist keine Ursache: Prüfen Sie, was auslöst, nur begünstigt oder lediglich später geschieht.",
  4:"Wissen ist gesichert, Absicht auf Handeln gerichtet und Deutung ein Verständnis der Situation.",
  5:"Ordnen Sie Ausgangslage, Anspannung, Zuspitzung, Wendepunkt und Folge nach ihrer Funktion im Verlauf.",
  8:"Die Ausgangslage ist gegenwärtig belegt; Vorgeschichte ist bereits geschehen, Nicht-Feststellbares wird nicht ergänzt.",
  9:"Paris’ Annahme über Romeo ist seine Deutung und kein gesichertes Wissen über Romeos Absicht.",
  10:"Das Ziel muss aus dem gewählten Wortlaut folgen; Beleg und Analyse dürfen keine fremde Absicht ergänzen.",
  12:"Unterscheiden Sie unmittelbares Verursachen, verstärkenden Beitrag und bloßes Später.",
  14:"Der Kampf ist der Wendepunkt, weil sich der Konflikt von Sprache zu körperlicher Gewalt mit irreversiblen Folgen verändert.",
  17:"Befürchtete Möglichkeiten in Juliettes Rede sind keine bereits eingetretenen Ereignisse.",
  19:"Die Figurenrede markiert den Entschluss; die originale Bühnenanweisung beschreibt dessen Ausführung.",
  20:"Textlich erwogen, situativ denkbar und unbelegt bezeichnen drei verschiedene Belegstärken.",
  22:"Die Abschlusskette braucht Verlauf, konkrete Kausalbeziehungen, Deutung, Primärtextbeleg, Analyse und Transfer.",
};
const hydrate=(value:unknown)=>hydrateSession(value,initialChapter04Session,22);

function readableChapter04Error(key:string){
 if(key.startsWith("final-curve:")){const attempted=key.slice("final-curve:".length).split("|");return attempted.flatMap((id,index)=>id===finalCurve[index]?.id?[]:[finalCurve.find(item=>item.id===id)?.label??id]).join(" · ")}
 const [rawId,rawTarget]=key.split(":");
 const id=rawId.replace(/^(intro|neutral|turn|tomb-action|tomb-turn)-/,"");
 const collections:readonly (readonly {id:string;label:string}[])[]=[introFacts,conflictTypes,historyPractice,causalIntro,generalEpistemicPractice,situationCards,knowledgeCards,escalationCards,internalPreparation,julietCards,julietAlternatives,comparisonAspects,finalConnections];
 const item=collections.flat().find(entry=>entry.id===id);
 const target=rawTarget&&labels[rawTarget]?` → gewählt: ${labels[rawTarget]}`:"";
 if(key.startsWith("general-goal-")){const task=generalGoalTasks.find(entry=>entry.id===rawId.slice("general-goal-".length));return `Zur Beobachtung „${task?.observation??rawId}“ wurde „${task?.options[Number(rawTarget)]??rawTarget}“ gewählt.`}
 if(key.startsWith("goal-choice-")){const task=goals.find(entry=>entry.id===rawId.slice("goal-choice-".length));return `${task?.character??"Figur"}: gewählt wurde „${task?.goalOptions[Number(rawTarget)]??rawTarget}“.`}
 if(key.startsWith("final-meaning-")){const selected=finalMeaningOptions.find(entry=>entry.id===key.slice("final-meaning-".length));return `Gewählte Deutung: „${selected?.label??key.slice("final-meaning-".length)}“`}
 if(key.startsWith("final-evidence-")){const selected=sourceById(key.slice("final-evidence-".length));return `Gewählter Textbeleg: „${selected?.text??key.slice("final-evidence-".length)}“`}
 if(key.startsWith("final-analysis-"))return `Gewählte Analyse: „${finalEvidence.analysisOptions[Number(key.slice("final-analysis-".length))]??key}“`;
 if(key.startsWith("final-transfer-")){const selected=finalTransferOptions.find(entry=>entry.id===key.slice("final-transfer-".length));return `Gewählter Transfer: „${selected?.label??key.slice("final-transfer-".length)}“`}
 if(key.startsWith("decision-"))return `Gewählte Zuordnung: „${key.slice("decision-".length)}“`;
 if(key.startsWith("comparison-")){const selected=key.slice("comparison-".length);return `Gewählte Synthese: „${selected}“`}
 return `${item?.label??"Die zuletzt geprüfte Auswahl"}${target}`;
}
function chapter04Resolution(key:string):string[]{
 const [rawId]=key.split(":");
 const id=rawId.replace(/^(intro|turn|tomb-turn)-/,"");
 const assignments=[...conflictTypes,...historyPractice,...causalIntro,...generalEpistemicPractice,...situationCards,...knowledgeCards,...escalationCards,...internalPreparation,...julietCards,...julietAlternatives,...comparisonAspects,...finalConnections] as readonly {id:string;label:string;target?:string;answer?:string;level?:string;kind?:string}[];
 const item=assignments.find(entry=>entry.id===id);
 const expected=item?.target??item?.answer??item?.level??item?.kind;
 if(item&&expected)return[`„${item.label}“ gehört zu „${labels[expected]??expected}“, weil diese Kategorie die im Text beziehungsweise Handlungsverlauf belegte Funktion des Elements bezeichnet.`];
 if(key==="curve-order")return dramaticCurve.map((entry,index)=>`${index+1}. ${entry.label}`).concat("Diese Reihenfolge führt von der Ausgangslage über Konflikt und Zuspitzung zum Wendepunkt und zur Folge.");
 if(key==="tomb-order")return chain.map((entry,index)=>`${index+1}. ${entry.label}`).concat("Die Reihenfolge folgt dem sichtbaren Verlauf von Paris’ Deutung über die gegensätzlichen Ziele und Reaktionen bis zum Kampf.");
 if(key==="monologue-order")return julietSequence.map((entry,index)=>`${index+1}. ${entry.label}`).concat("Die Ordnung folgt Situation, erwogenen Möglichkeiten, Abwägung, Entscheidung und Ausführung; vorgestellte Folgen sind noch keine Ereignisse.");
 if(key.startsWith("final-curve"))return finalCurve.map((entry,index)=>`${index+1}. ${entry.label}`).concat("Die Abschlussfolge rekonstruiert den belegten Verlauf, ohne bloße zeitliche Nähe als Ursache auszugeben.");
 if(key.startsWith("general-goal-")){const goalId=key.slice("general-goal-".length).split(":")[0];const task=generalGoalTasks.find(entry=>entry.id===goalId);if(task)return[`Richtig ist „${task.options[task.answer]}“, weil dieses Ziel aus dem beschriebenen Verhalten erschlossen wird.`]}
 if(key.startsWith("general-evidence-")){const taskId=key.slice("general-evidence-".length).split(":")[0];const task=generalEvidenceTasks.find(entry=>entry.id===taskId);if(task)return[`Richtig sind „${task.evidenceOptions[task.evidenceAnswer]}“ und „${task.analysisOptions[task.analysisAnswer]}“, weil der Beleg die Behauptung unmittelbar trägt und die Analyse seine Funktion erklärt.`]}
 if(key.startsWith("goal-choice-")){const goalId=key.slice("goal-choice-".length).split(":")[0];const task=goals.find(entry=>entry.id===goalId);if(task)return[`Richtig ist „${task.goalOptions[task.goalAnswer]}“, weil dieses Ziel die konkrete Handlungsabsicht der Figur in der Szene beschreibt.`]}
 if(key.startsWith("goal-")&&!key.startsWith("goal-choice-")){const goalId=key.slice("goal-".length).split(":")[0];const task=goals.find(entry=>entry.id===goalId);if(task)return[`Richtig sind der Beleg „${task.evidence}“ und die Analyse „${task.analysis}“, weil beide das zuvor erschlossene Ziel der Figur unmittelbar stützen.`]}
 if(key.startsWith("relation-")){const from=key.slice("relation-".length).split(":")[0];const link=chainLinks.find(entry=>entry.from===from);if(link)return[`„${chain.find(entry=>entry.id===link.from)?.label} → ${chain.find(entry=>entry.id===link.to)?.label}“ gehört zu „${labels[link.type]??link.type}“, weil genau diese Stärke des Zusammenhangs durch den Verlauf belegt ist.`]}
 if(key.startsWith("decision-"))return["Richtig ist: Juliettes an Romeo gerichtete Worte markieren den Entschluss; die originale Bühnenanweisung beschreibt dessen körperlichen Vollzug. Figurenrede und Bühnenhandlung erfüllen hier verschiedene Funktionen."];
 if(key.startsWith("incompatibility-"))return["Richtig ist: Beide Ziele können nicht zugleich verwirklicht werden, weil Paris Romeo festhalten und Romeo seinen eigenen Weg fortsetzen will."];
 if(key.startsWith("turn-reason-")||key.startsWith("tomb-turn-"))return["Der Beginn des Fechtens ist der zentrale Wendepunkt, weil aus dem sprachlichen Konflikt körperliche Gewalt mit irreversiblen Folgen wird."];
 if(key.startsWith("turn-")){const id=key.slice("turn-".length).split(":")[0];const task=neutralTurningPoints.find(entry=>entry.id===id);if(task)return[`„${task.label}“ ist als „${task.judgement==="turning"?"Zentraler Wendepunkt":"Wichtige Zuspitzung"}“ einzuordnen, weil davor ${task.before.toLowerCase()}, sich dann ${task.change.toLowerCase()} und danach ${task.after.toLowerCase()}`]}
 if(key.startsWith("comparison-"))return["Vertretbar sind: „Im äußeren Verlauf treiben gegenseitige Handlungen den Konflikt; im inneren Verlauf führt eine Abwägung zur Entscheidung und Ausführung.“ sowie die Unterscheidung von Dialog/Bühnenhandlung und Monolog/Entscheidung. Beide vergleichen Konfliktträger, Darstellung und Entwicklung textnah."];
 if(key.startsWith("final-meaning-")){const valid=finalMeaningOptions.find(entry=>entry.valid);return[`Richtig ist „${valid?.label}“, weil diese Deutung Situationsverständnis, unvereinbare Ziele und den belegten Umschlag in Gewalt zusammenführt, ohne fremde Absichten zu ergänzen.`]}
 if(key.startsWith("final-evidence-"))return[`Richtig ist „${sourceById(finalEvidence.evidence)?.text??finalEvidence.evidence}“, weil diese originale Bühnenanweisung den Wechsel vom Wortkonflikt zum körperlichen Kampf unmittelbar markiert.`];
 if(key.startsWith("final-analysis-"))return[`Richtig ist „${finalEvidence.analysisOptions[finalEvidence.analysisAnswer]}“, weil die Analyse Textsignal, Konfliktform und irreversible Folge miteinander verbindet.`];
 if(key.startsWith("final-transfer-")){const valid=finalTransferOptions.filter(entry=>entry.valid).map(entry=>`„${entry.label}“`);return[`Vertretbar sind ${valid.join(" oder ")}, weil beide äußeren und inneren Konflikt nach Handlungsentstehung und Darstellung vergleichen.`]}
 if(key.startsWith("goals-"))return["Richtig ist „Mara: Feier · Vater: Lernen“, weil Mara zur Feier gehen will und ihr Vater das Lernen zu Hause erwartet."];
 if(key.startsWith("intro-")){const fact=introFacts.find(entry=>`intro-${entry.id}`===key);if(fact)return[`„${fact.label}“ ist ${fact.relevant?"konfliktrelevant":"nicht konfliktentscheidend"}, weil nur unvereinbare Handlungsziele den beschriebenen Gegensatz erzeugen.`]}
 if(["fight","paris_falls","peace"].includes(id)){const expectedConsequence=id==="fight"?"immediate":id==="paris_falls"?"farther":"not_determinable";return[`„${id==="fight"?"Der Konflikt wird körperlich.":id==="paris_falls"?"Paris fällt im Kampf.":"Ohne Kampf wäre sicher Frieden entstanden."}“ gehört zu „${labels[expectedConsequence]}“, weil ${id==="fight"?"dies den unmittelbaren Umschlag bezeichnet":id==="paris_falls"?"dies eine weitere körperliche Folge ist":"diese kontrafaktische Entwicklung nicht sicher feststellbar ist"}.`]}
 return["Die konkrete richtige Auswahl ist in der Aufgabenauflösung benannt; sie trägt, weil sie mit dem sichtbaren Text- und Handlungszusammenhang übereinstimmt."];
}
function chapter04OrderDetails(attempted:string[],correct:readonly {id:string;label:string}[],why:string):FailureDetails{return{incorrectItems:attempted.flatMap((id,index)=>id===correct[index]?.id?[]:[correct.find(item=>item.id===id)?.label??id]),resolution:correct.map((item,index)=>`${index+1}. ${item.label}`).concat(why)}}

export function Chapter04({gameState,onSave,onExit,onComplete}:Props){
 const[s,setS]=useState(()=>hydrate(gameState.decisions.chapter_04));const[feedback,setFeedback]=useState("Rekonstruieren Sie, wie Konflikte dramatische Handlung antreiben.");const[last,setLast]=useState<{key:string;valid:boolean}|null>(null);
 const support=useLearningSupport(`chapter04-${s.round}`);
 useEffect(()=>{document.querySelector(".causal-board")?.scrollIntoView({block:"start",behavior:"auto"})},[s.round]);
 const apply=(r:Result,key="",ok="✓ Fachlich tragfähig.",wrong="Noch einmal prüfen: Welche Text- oder Handlungsbeziehung ist tatsächlich belegt?",details?:FailureDetails)=>{setS(r.session);onSave(r.session);setLast({key,valid:r.valid});setFeedback(r.valid?ok:`↺ ${wrong}`);if(r.valid)support.reset();else{const solution=chapter04SecondHints[s.round]??"Prüfen Sie, ob die Beziehung Ursache, beitragende Bedingung, Reaktion, Folge oder bloße zeitliche Nähe bezeichnet.";support.registerFailure(wrong,solution,details??{incorrectItems:[readableChapter04Error(key)],resolution:chapter04Resolution(key)})}};
 const assist=()=>{const next=advanceWithSupport(s,22);setS(next);onSave(next);support.reset();setLast(null);setFeedback("Mit Unterstützung abgeschlossen. Die folgende Rekonstruktion greift die geklärte Beziehung wieder auf.");if(next.completed)onComplete(next)};
 const finish=()=>{const r=completeChapter04(s);apply(r,"finish","✓ Beleg, Kausalverlauf und Transfer bilden eine vollständige Analyse.","Die Rekonstruktion braucht konkrete Kausalbeziehungen, einen Primärtextbeleg und den Transfer auf den inneren Konflikt.");if(r.valid)onComplete(r.session)};
 const inner=s.round>=15;
 return <main className="chapter chapter-04-causality"><header className="chapter-top"><button onClick={onExit}>Zurück zum Theater</button><div><small>Kapitel 4</small><h1>Der Punkt ohne Rückkehr</h1><p>Handlungsverläufe in Dramaszenen rekonstruieren</p></div><span className="round-mark">Station {s.round}/22</span></header><section className={`causal-stage ${inner?"inner-conflict":"tomb-conflict"}`} aria-label={inner?"Innerer Konflikt":"Handlungs- und Konfliktanalyse"}><AssetImage id={inner?"bg_analysis_room":"bg_tomb_stage"} className="asset-backdrop" loading="eager" decorative/>{s.round>=8&&<SceneCharacters sceneId={inner?"chapter_04.juliet":"chapter_04.tomb"}/>}<article className="causal-board" tabIndex={-1}><GlossaryHelp entries={glossaryFor("chapter_04")} introTitle="Werkzeuge der Handlungsanalyse" introEntryIds={["external_conflict","internal_conflict","causality","contributing_condition"]} seen={s.seenGlossaryIntroductions.includes("chapter_04")} onSeen={()=>{const n={...s,seenGlossaryIntroductions:[...new Set([...s.seenGlossaryIntroductions,"chapter_04"])]};setS(n);onSave(n)}}/><TaskInstruction>{chapter04Tasks[s.round]}</TaskInstruction><Round s={s} apply={apply} last={last} finish={finish} onLocalFailure={(message,resolution)=>{setLast({key:"local",valid:false});setFeedback(`↺ ${message}`);const solution=chapter04SecondHints[s.round]??message;support.registerFailure(message,solution,{incorrectItems:[message],resolution:[resolution]})}}/><LearningSupport state={support} onAssist={assist}/></article></section><div className={`feedback-bar ${last?.valid?"is-correct":last?"is-incorrect":""}`} role="status" aria-live="polite"><span aria-hidden="true">{last?.valid?"✓":last?"!":"◆"}</span>{feedback}</div></main>;
}

function Round({s,apply,last,finish,onLocalFailure}:{s:Chapter04Session;apply:(r:Result,key?:string,ok?:string,wrong?:string,details?:FailureDetails)=>void;last:{key:string;valid:boolean}|null;finish:()=>void;onLocalFailure:(message:string,resolution:string)=>void}){
 const next=(expected:number,patch:Partial<Chapter04Session>={})=>apply(advanceChapter04(s,expected,patch),`next-${expected}`);
 if(s.round===1){const goal=generalGoalTasks.find(x=>!s.generalGoals.includes(x.id));return <><Kicker>Grundlagen · Konfliktinformationen und Ziele</Kicker><h2>Welche Informationen erzeugen den Konflikt?</h2><p>Mara möchte zu einer Feier gehen. Ihr Vater erwartet, dass sie zu Hause lernt.</p><ChoiceGrid items={introFacts} selected={s.introRelevant} onPick={id=>apply(selectIntroFact(s,id),`intro-${id}`,"✓ Diese Information bestimmt ein Ziel.","Die Aussage ist für den Konflikt nicht entscheidend.")}/>{s.introRelevant.length===2&&!Object.keys(s.introGoals).length&&<Choice title="Welche Ziele treffen aufeinander?" options={[{id:"right",label:"Mara: Feier · Vater: Lernen"},{id:"wrong",label:"Mara: Lernen · Vater: Feier"}]} onPick={id=>apply(saveIntroGoals(s,id==="right"?"party":"study",id==="right"?"study":"party"),`goals-${id}`,"✓ Die unvereinbaren Ziele sind erkannt.")}/>} {Object.keys(s.introGoals).length===2&&goal&&<Choice title={`Welches Ziel lässt sich aus diesem Verhalten erschließen? ${goal.observation}`} options={goal.options.map((label,i)=>({id:String(i),label}))} onPick={id=>apply(solveGeneralGoal(s,goal.id,Number(id)),`general-goal-${goal.id}:${id}`,"✓ Das Ziel wird aus Aussage und Handlung erschlossen.","Trennen Sie Ziel, Wissen, Reaktion und Folge.")}/>}</>}
 if(s.round===2){const conflictsDone=Object.keys(s.conflictAssignments).length===conflictTypes.length;return <>{!conflictsDone?<Assign title="Äußerer oder innerer Konflikt?" items={conflictTypes} targets={["external","internal"]} done={s.conflictAssignments} last={last} onPick={(id,t)=>apply(assignConflictType(s,id,t),`${id}:${t}`,t==="external"?"✓ Zwei Konfliktträger verfolgen unvereinbare Ziele.":"✓ Gegensätzliche Kräfte wirken innerhalb derselben Figur.","Liegt der Gegensatz zwischen Figuren oder innerhalb derselben Figur?")}/>:<Assign title="Vorgeschichte knapp reaktivieren" intro="Vorgeschichte umfasst vorausgegangene Ereignisse, die den aktuellen Konflikt verständlich machen." items={historyPractice} targets={["history","current","knowledge","future","irrelevant"]} done={s.historyAssignments} last={last} onPick={(id,t)=>apply(assignHistory(s,id,t),`${id}:${t}`,"✓ Die Information ist zeitlich und funktional passend eingeordnet.","Prüfen Sie: bereits geschehen, gegenwärtig, gewusst, nur vermutet oder irrelevant?")}/>}</>}
 if(s.round===3)return <Assign title="Ursache, beitragende Bedingung oder nur später?" intro="Eine Ursache löst eine Folge wesentlich aus. Eine beitragende Bedingung begünstigt oder verstärkt sie, ohne allein auszureichen." items={causalIntro} targets={["causes","contributes","only_later"]} done={s.causalIntroAssignments} last={last} onPick={(id,t)=>apply(assignCausalIntro(s,id,t),`${id}:${t}`,t==="contributes"?"✓ Dieser Umstand verstärkt die Entwicklung, löst sie aber nicht allein aus.":"✓ Die Ereignisbeziehung ist begründet eingeordnet.","Prüfen Sie den Sachzusammenhang, nicht nur die zeitliche Reihenfolge.")}/>;
 if(s.round===4){const epistemicDone=Object.keys(s.generalEpistemicAssignments).length===generalEpistemicPractice.length;const evidenceTask=generalEvidenceTasks.find(x=>!s.generalEvidence.includes(x.id));if(!epistemicDone)return <Assign title="Wissensstand, Absicht oder Deutung?" intro="Wissen betrifft gesicherte Information; Absicht ein angestrebtes Handeln; Deutung das Verständnis einer Situation." items={generalEpistemicPractice} targets={["knowledge","intention","interpretation","unsupported"]} done={s.generalEpistemicAssignments} last={last} onPick={(id,t)=>apply(assignGeneralEpistemic(s,id,t),`${id}:${t}`,"✓ Die Aussage ist der richtigen Erkenntnisebene zugeordnet.","Prüfen Sie, ob die Figur etwas sicher kennt, erreichen will oder interpretiert.")}/>;if(evidenceTask)return <GeneralEvidence task={evidenceTask} onSolve={(a,b)=>apply(solveGeneralEvidence(s,evidenceTask.id,a,b),`general-evidence-${evidenceTask.id}:${a}:${b}`,"✓ Beleg und Analyse stützen gemeinsam die Behauptung.","Ein passender Beleg reicht erst mit einer präzisen Analyse.",{incorrectItems:[`Gewählt wurden „${evidenceTask.evidenceOptions[a]}“ und „${evidenceTask.analysisOptions[b]}“.`],resolution:chapter04Resolution(`general-evidence-${evidenceTask.id}`)})}/>;return <><Kicker>Analysewerkzeug</Kicker><h2>Dramatische Handlung entwickelt sich</h2><p>Eine dramatische Szene besteht nicht nur aus einzelnen Ereignissen. Figuren verfolgen Ziele, reagieren aufeinander und verändern dadurch die Situation. Konflikte können sich verdichten und einen Wendepunkt erreichen.</p><div className="drama-curve" aria-label="Verlaufskurve als Analysewerkzeug">{["Ausgangslage","Konflikt / Anspannung","Zuspitzung","Wendepunkt","Folge"].map((x,i)=><span key={x}>{x}{i<4&&<b>→</b>}</span>)}</div><p><strong>Diese Verlaufskurve ist ein Analysewerkzeug.</strong> Nicht jede Szene und nicht jedes Drama folgt demselben festen Schema.</p><button className="primary-action" onClick={()=>next(4,{curveIntroduced:true})}>Verlaufskurve anwenden</button></>}
 if(s.round===5)return s.curveOrder.length===dramaticCurve.length?<><Kicker>Analytische Sicherung</Kicker><h2>Funktionen im Handlungsverlauf</h2><ol className="final-method">{dramaticCurve.map(item=><li key={item.id}><strong>{labels[item.stage]??item.stage}</strong><span>{item.label}</span></li>)}</ol><p>Die Einordnung ist ein Analysevorschlag für diesen Verlauf, kein universelles Dramaschema.</p><button className="primary-action" onClick={()=>next(5)}>Analyse sichern</button></>:<Sorter title="Eine allgemeine Handlungskurve rekonstruieren" items={[...dramaticCurve].reverse()} onSolve={ids=>apply(setCurveOrder(s,ids),"curve-order","✓ Die Reihenfolge stimmt. Prüfen Sie nun die Funktion jedes Ereignisses im Verlauf.",undefined,chapter04OrderDetails(ids,dramaticCurve,"Die Ordnung führt von Ausgangslage und Konflikt über Zuspitzung und Wendepunkt zur Folge."))}/>;
 if(s.round===6)return <ActionChains title="Handlung → Reaktion → Folge" tasks={neutralActionChains} done={s.neutralActionChains} onSolve={(id,a,b,c)=>apply(solveNeutralActionChain(s,id,a,b,c),`neutral-${id}`,"✓ Impuls, unmittelbare Reaktion und Veränderung passen zusammen.")} onFailure={onLocalFailure}/>;
 if(s.round===7)return <Turning title="Wendepunkte allgemein prüfen" items={neutralTurningPoints} onPick={(id,j)=>apply(chooseNeutralTurning(s,id,j),`turn-${id}:${j}`,"✓ Davor, Veränderung und Danach begründen das Urteil.","Vergleichen Sie Davor, Veränderung und Danach.")}/>;
 if(s.round===8)return <Shakespeare ids={["c04_tomb_romeo_order","c04_tomb_paris_view"]}><Kicker>Äußerer Konflikt · Ausgangslage</Kicker><h2>Die Situation an der Gruft rekonstruieren</h2><p className="orientation">Juliette gilt als tot und ist in der Familiengruft bestattet. Paris besucht die Gruft; Romeo kehrt heimlich zurück.</p><Assign items={situationCards} targets={["situation","prior","not_determinable"]} done={s.situationAssignments} last={last} onPick={(id,t)=>apply(assignSituation(s,id,t),`${id}:${t}`)}/></Shakespeare>;
 if(s.round===9)return <Shakespeare ids={["c04_tomb_romeo_order","c04_tomb_paris_view","c04_tomb_romeo_leave","c04_tomb_paris_arrest"]}><Kicker>Wissen, Absicht und Deutung trennen</Kicker><Assign title="Welche Erkenntnisebene ist textlich gestützt?" items={knowledgeCards} targets={["romeo_knowledge","romeo_intention","paris_knowledge","paris_interpretation","paris_intention","unsupported"]} done={s.knowledgeAssignments} last={last} onPick={(id,t)=>apply(assignKnowledge(s,id,t),`${id}:${t}`,"✓ Wissen, Absicht und Deutung bleiben getrennt.")}/></Shakespeare>;
 if(s.round===10)return <Shakespeare ids={["c04_tomb_romeo_order","c04_tomb_paris_view","c04_tomb_paris_arrest","c04_tomb_romeo_leave","c04_tomb_romeo_warning"]}><Kicker>Ziel → Beleg → Analyse</Kicker><Goals s={s} apply={apply}/>{s.goalAnalyses.length===goals.length&&<Choice title="Warum entsteht daraus ein Konflikt?" options={[{id:"cannot_both_succeed",label:"Beide Ziele können nicht zugleich verwirklicht werden."},{id:"same_goal",label:"Beide Figuren verfolgen dasselbe Ziel."},{id:"knowledge_only",label:"Nur ihr unterschiedlicher Wissensstand bildet bereits den ganzen Konflikt."}]} onPick={id=>apply(setIncompatibility(s,id),`incompatibility-${id}`,"✓ Die unvereinbaren Ziele tragen den äußeren Konflikt.")}/>}</Shakespeare>;
 if(s.round===11)return <Shakespeare ids={["c04_tomb_paris_view","c04_tomb_paris_arrest","c04_tomb_romeo_leave","c04_tomb_paris_reject","c04_tomb_fight"]}><Sorter title="Handlungskette der Gruftszene" items={[...chain].reverse()} onSolve={ids=>{let n=s;for(const id of ids)n=placeChainEvent(n,id).session;apply({valid:n.chainOrder.length===chain.length,session:n},"tomb-order","✓ Die Schritte haben jeweils eine eigene Funktion im Verlauf.",undefined,chapter04OrderDetails(ids,chain,"Die Reihenfolge folgt Paris’ Deutung, den gegensätzlichen Handlungen und Reaktionen bis zum Kampf."))}}/></Shakespeare>;
 if(s.round===12)return <Shakespeare ids={["c04_tomb_paris_view","c04_tomb_paris_arrest","c04_tomb_romeo_leave","c04_tomb_paris_reject","c04_tomb_fight"]}><Relations s={s} apply={apply}/></Shakespeare>;
 if(s.round===13)return <Shakespeare ids={["c04_tomb_romeo_leave","c04_tomb_paris_reject","c04_tomb_romeo_warning","c04_tomb_fight"]}><ActionChains title="Handlung → Reaktion → Veränderung" tasks={tombActionChains} done={s.tombActionChains} onSolve={(id,a,b,c)=>apply(solveTombActionChain(s,id,a,b,c),`tomb-action-${id}`,"✓ Die unmittelbare Reaktion und ihre Wirkung sind textnah verbunden.")} onFailure={onLocalFailure}/></Shakespeare>;
 if(s.round===14)return <Shakespeare ids={["c04_tomb_romeo_warning","c04_tomb_paris_reject","c04_tomb_fight"]}><Kicker>Eskalation und Wendepunkt</Kicker><Assign items={escalationCards} targets={["tension","escalation","turning"]} done={s.escalationAssignments} last={last} onPick={(id,t)=>apply(assignEscalation(s,id,t),`${id}:${t}`)}/>{Object.keys(s.escalationAssignments).length===3&&!s.turningPoint&&<Turning title="Wodurch verändert sich der weitere Verlauf?" items={[{id:"appeal",label:"Romeos Aufforderung",before:"Romeo will Paris zum Fortgehen bewegen.",change:"Paris bleibt bei seinem Ziel.",after:"Der Konflikt besteht weiter.",judgement:"escalation"},{id:"fight",label:"Beginn des Fechtens",before:"Der Konflikt wird sprachlich ausgetragen.",change:"Die Figuren gehen zum körperlichen Kampf über.",after:"Der Konflikt wird nicht mehr ausschließlich sprachlich geführt; der Kampf führt zu irreversiblen Folgen.",judgement:"turning"}]} onPick={(id,j)=>apply(chooseTurningPoint(s,j==="turning"?id:""),`tomb-turn-${id}:${j}`)}/>} {s.turningPoint&&!s.turningReason&&<Choice title="Warum ist dieser Übergang als Wendepunkt begründbar?" options={[{id:"dramatic",label:"Weil an dieser Stelle etwas besonders Dramatisches geschieht."},{id:"form_irreversible",label:"Die Konfliktform verändert sich: Aus Sprache wird körperliche Gewalt mit nicht rücknehmbaren Folgen."},{id:"later",label:"Weil das Fechten im Text später steht als Romeos Warnung."}]} onPick={id=>apply(explainTurningPoint(s,id),`turn-reason-${id}`,"✓ Der Übergang verändert die Konfliktform und eröffnet irreversible Folgen.","Ein Wendepunkt ist nicht bloß besonders dramatisch oder zeitlich später.")}/>} {s.turningReason&&<Assign title="Folgen differenzieren" items={[{id:"fight",label:"Der Konflikt wird körperlich."},{id:"paris_falls",label:"Paris fällt im Kampf."},{id:"peace",label:"Ohne Kampf wäre sicher Frieden entstanden."}]} targets={["immediate","farther","not_determinable"]} done={s.consequences} last={last} onPick={(id,t)=>apply(assignConsequence(s,id,t),`${id}:${t}`)}/>}</Shakespeare>;
 if(s.round===15)return <><Kicker>Vorbereitung · innerer Konflikt</Kicker><Assign title="Wunsch, Befürchtung, Abwägung, Entscheidung oder Ausführung?" items={internalPreparation} targets={["wish","fear","weighing","decision","execution"]} done={s.internalPreparation} last={last} onPick={(id,t)=>apply(assignInternalPreparation(s,id,t),`${id}:${t}`)}/></>;
 if(s.round===16)return <Shakespeare ids={["c04_juliet_alone","c04_juliet_no_marriage","c04_juliet_poison_fear","c04_juliet_tomb_fear","c04_juliet_drinks","c04_juliet_execution"]}><Kicker>Transfer auf Juliettes Monolog</Kicker><h2>Juliette allein vor der Phiole</h2><p>Juliette steht vor einer Entscheidung und wägt mögliche Folgen ab. Rekonstruieren Sie den inneren Handlungsverlauf aus dem Text.</p><button className="primary-action inner-conflict-action" onClick={()=>next(16)}>Den inneren Konflikt untersuchen</button></Shakespeare>;
 if(s.round===17)return <Shakespeare ids={["c04_juliet_alone","c04_juliet_no_marriage","c04_juliet_poison_fear","c04_juliet_tomb_fear","c04_juliet_drinks","c04_juliet_execution"]}><Assign title="Juliettes innere Konfliktstruktur" intro="Eine vorgestellte Folge ist noch kein tatsächliches Ereignis." items={julietCards} targets={["situation","supports_action","feared_possibility","decision","execution"]} done={s.julietAssignments} last={last} onPick={(id,t)=>apply(assignJuliet(s,id,t),`${id}:${t}`,t==="feared_possibility"?"✓ Als vorgestellte Möglichkeit erkannt – nicht als eingetretene Folge.":undefined)}/></Shakespeare>;
 if(s.round===18)return <Shakespeare ids={["c04_juliet_alone","c04_juliet_no_marriage","c04_juliet_poison_fear","c04_juliet_tomb_fear","c04_juliet_drinks","c04_juliet_execution"]}><Sorter title="Phasen der Abwägung rekonstruieren" items={[...julietSequence].reverse()} onSolve={ids=>{let n=s;for(const id of ids)n=placeMonologueStep(n,id).session;apply({valid:n.monologueOrder.length===julietSequence.length,session:n},"monologue-order","✓ Die Befürchtungen bleiben eine gemeinsame Phase statt einer künstlichen Rangfolge.",undefined,chapter04OrderDetails(ids,julietSequence,"Die Ordnung folgt Ausgangslage, Gegenkräften, Abwägung, Entscheidung und erst danach der Ausführung."))}}/></Shakespeare>;
 if(s.round===19)return <Shakespeare ids={["c04_juliet_drinks","c04_juliet_execution"]}><Kicker>Entscheidung ≠ Ausführung</Kicker><Choice title="Welche Zuordnung ist textlich belegt?" options={[{id:"words_stage",label:"Juliettes an Romeo gerichtete Worte markieren den Entschluss; die Bühnenanweisung beschreibt den Vollzug."},{id:"stage_words",label:"Die Bühnenanweisung bildet den Entschluss; Juliettes Worte führen ihn körperlich aus."},{id:"both_decision",label:"Beide Stellen bezeichnen nur den Entschluss, eine Ausführung bleibt unbelegt."},{id:"both_execution",label:"Beide Stellen zeigen ausschließlich den körperlichen Vollzug."}]} onPick={id=>apply(distinguishDecision(s,id==="words_stage"?"c04_juliet_drinks":"c04_juliet_execution",id==="words_stage"?"c04_juliet_execution":"c04_juliet_drinks"),`decision-${id}`,"✓ Figurenrede und Bühnenanweisung erfüllen verschiedene Funktionen.")}/></Shakespeare>;
 if(s.round===20)return <Shakespeare ids={["c04_juliet_no_marriage","c04_juliet_poison_fear","c04_juliet_tomb_fear"]}><Assign title="Handlungsalternativen und Belegstatus" intro="Situativ plausibel bedeutet: Unter den gegebenen Umständen wäre diese Möglichkeit denkbar. Das bedeutet nicht, dass Juliette sie tatsächlich erwägt." items={julietAlternatives} targets={["textual","plausible","unsupported"]} done={s.julietAlternatives} last={last} onPick={(id,t)=>apply(assignJulietAlternative(s,id,t),`${id}:${t}`,"✓ Textlich erwogen, situativ plausibel und unbelegt sind getrennt.","Plausibilität und tatsächlich erwogener Gedanke sind nicht dasselbe.")}/></Shakespeare>;
 if(s.round===21)return <><Kicker>Äußeren und inneren Konflikt vergleichen</Kicker><Assign items={comparisonAspects} targets={["external","internal"]} done={s.comparisonAssignments} last={last} onPick={(id,t)=>apply(assignComparison(s,id,t),`${id}:${t}`)}/>{Object.keys(s.comparisonAssignments).length===comparisonAspects.length&&<><ComparisonTable/><Choice title="Vergleichende Synthese" options={[{id:"external_vs_internal",label:"Im äußeren Verlauf treiben gegenseitige Handlungen den Konflikt; im inneren Verlauf führt eine Abwägung zur Entscheidung und Ausführung."},{id:"representation_difference",label:"Beide Konflikte verändern Handlungsmöglichkeiten, werden aber durch Dialog und Bühnenhandlung beziehungsweise durch Monolog und Entscheidung unterschiedlich dargestellt."},{id:"both_external",label:"Beide Konflikte entstehen zwischen gleichzeitig anwesenden Figuren, werden aber unterschiedlich heftig ausgetragen."}]} onPick={id=>apply(compareConflicts(s,id),`comparison-${id}`,"✓ Die Synthese ist textnah und unterscheidet die Verlaufsformen.","Prüfen Sie Konfliktträger, Darstellung und Entwicklung gemeinsam.")}/></>}</>;
 return <FinalRound s={s} apply={apply} last={last} finish={finish}/>;
}

function FinalRound({s,apply,last,finish}:{s:Chapter04Session;apply:(r:Result,key?:string,ok?:string,wrong?:string)=>void;last:{key:string;valid:boolean}|null;finish:()=>void}){return <Shakespeare ids={["c04_tomb_romeo_order","c04_tomb_paris_view","c04_tomb_paris_arrest","c04_tomb_romeo_leave","c04_tomb_romeo_warning","c04_tomb_paris_reject","c04_tomb_fight"]}><Kicker>Abschlussrekonstruktion</Kicker><h2>Vom Textbefund zur Bedeutung</h2>{s.finalCurve.length===0?<Sorter title="Teil A · Handlungsverlauf rekonstruieren" items={[...finalCurve].reverse()} onSolve={ids=>apply(setFinalCurve(s,ids),`final-curve:${ids.join("|")}`)}/>:<><ol className="final-method">{finalCurve.map((x,i)=><li key={x.id}><strong>{i+1}. {labels[x.stage]??x.stage}</strong><span>{x.label}</span></li>)}</ol><Assign title="Konkrete Übergänge kausal beurteilen" items={finalConnections} targets={["causes","contributes","only_later"]} done={s.finalAssignments} last={last} onPick={(id,t)=>apply(assignFinalRelation(s,id,t),`${id}:${t}`)}/>{Object.keys(s.finalAssignments).length===finalConnections.length&&!s.finalMeaning&&<Choice title="Teil B · Welche Deutung wird durch den Verlauf gestützt?" options={finalMeaningOptions.map(x=>({id:x.id,label:x.label}))} onPick={id=>apply(setFinalMeaning(s,id),`final-meaning-${id}`,"✓ Die Deutung verbindet Situationsdeutung, Ziele und den Umschlag in körperliche Gewalt.","Die Deutung darf weder unbelegte Absichten ergänzen noch den Verlauf zum allgemeinen Gesetz erklären.")}/>} {s.finalMeaning&&!s.finalEvidence&&<EvidenceChoice title={`Welcher Primärtextbeleg stützt die Teilbehauptung: ${finalEvidence.claim}`} ids={finalEvidence.evidenceOptions} onPick={id=>apply(setFinalEvidence(s,id),`final-evidence-${id}`,"✓ Die Bühnenanweisung belegt den Wechsel zum körperlichen Konflikt.","Prüfen Sie, welcher Wortlaut den behaupteten Wendepunkt unmittelbar markiert.")}/>} {s.finalEvidence&&s.finalEvidenceAnalysis===undefined&&<Choice title="Was zeigt der Beleg für den Handlungsverlauf?" options={finalEvidence.analysisOptions.map((label,i)=>({id:String(i),label}))} onPick={id=>apply(setFinalEvidenceAnalysis(s,Number(id)),`final-analysis-${id}`,"✓ Die Analyse erklärt die Funktion des Belegs für Verlauf und Bedeutung.")}/>} {s.finalEvidenceAnalysis!==undefined&&!s.finalTransfer&&<Choice title="Was zeigt der Vergleich beider Konfliktverläufe über dramatische Handlung?" options={finalTransferOptions.map(x=>({id:x.id,label:x.label}))} onPick={id=>apply(setFinalTransfer(s,id),`final-transfer-${id}`,"✓ Dramatische Handlung entsteht sowohl zwischen Figuren als auch aus widerstreitenden Möglichkeiten innerhalb einer Figur.","Prüfen Sie, wie Konflikte Entscheidungen, Reaktionen und Veränderungen hervorbringen.")}/>} {s.finalTransfer&&<><div className="learning-result"><h3>BEHAUPTUNG → TEXTBELEG → ANALYSE → BEDEUTUNG</h3><p><strong>DEUTUNG:</strong> {finalMeaningOptions.find(x=>x.id===s.finalMeaning)?.label}</p><p><strong>TEXTBELEG:</strong> ausgewählte originale Bühnenanweisung</p><p><strong>ANALYSE / WIRKUNG:</strong> {finalEvidence.analysisOptions[finalEvidence.analysisAnswer]}</p><strong>TEXTBEFUND → KONFLIKT → HANDLUNG → VERÄNDERUNG → DEUTUNG</strong></div><button className="primary-action" onClick={finish}>Handlungsbuch restaurieren</button></>}</>}</Shakespeare>}
function ComparisonTable(){return <div className="comparison-summary" role="table" aria-label="Vergleich äußerer und innerer Konflikt"><div role="row"><strong role="columnheader">Analyseaspekt</strong><strong role="columnheader">Romeo / Paris</strong><strong role="columnheader">Juliette</strong></div>{comparisonSummary.map(row=><div role="row" key={row.aspect}><strong role="rowheader">{row.aspect}</strong><span role="cell">{row.external}</span><span role="cell">{row.internal}</span></div>)}</div>}
function Kicker({children}:{children:ReactNode}){return <p className="chapter-kicker">{children}</p>}
function Choice({title,options,onPick}:{title:string;options:readonly {id:string;label:string}[];onPick:(id:string)=>void}){const presented=stablePresentationOrder(options,`chapter04-choice-${title}`);return <fieldset className="causal-choice"><legend>{title}</legend><TaskInstruction>Wählen Sie genau eine Antwort. Entscheiden Sie anhand des belegten Konflikt-, Wissens- oder Handlungszusammenhangs.</TaskInstruction>{presented.map(x=><button key={x.id} onClick={()=>onPick(x.id)}>{x.label}</button>)}</fieldset>}
function ChoiceGrid({items,selected,onPick}:{items:readonly {id:string;label:string}[];selected:string[];onPick:(id:string)=>void}){const presented=stablePresentationOrder(items,`chapter04-grid-${items.map(item=>item.id).join("-")}`);return <div><TaskInstruction>Wählen Sie alle Aussagen, die den beschriebenen Konflikt unmittelbar bestimmen. Prüfen Sie jede Auswahl an den erkennbaren Zielen der Beteiligten.</TaskInstruction><div className="choice-grid">{presented.map(x=><button className={selected.includes(x.id)?"answer-correct":""} key={x.id} disabled={selected.includes(x.id)} onClick={()=>onPick(x.id)}>{selected.includes(x.id)&&<span className="answer-status">✓ Richtig · </span>}{x.label}</button>)}</div></div>}
function Assign({title,intro,items,targets,done,last,onPick}:{title?:string;intro?:string;items:readonly {id:string;label:string}[];targets:string[];done:Record<string,string>;last:{key:string;valid:boolean}|null;onPick:(id:string,target:string)=>void}){const presented=stablePresentationOrder(items,`chapter04-assign-${title??items.map(item=>item.id).join("-")}`);return <div className="assignment-board">{title&&<h2>{title}</h2>}{intro&&<p>{intro}</p>}<TaskInstruction>Ordnen Sie jede Aussage genau einer Kategorie zu. Prüfen Sie dabei, welche Funktion oder Belegstärke sie im konkreten Konflikt- und Handlungsverlauf besitzt.</TaskInstruction>{presented.map(item=><fieldset key={item.id}><legend>{"dimension" in item&&typeof item.dimension==="string"?<><small>{item.dimension}</small><br/>{item.label}</>:item.label}</legend>{targets.map(target=>{const correct=done[item.id]===target,wrong=last?.key===`${item.id}:${target}`&&!last.valid;return <button className={correct?"answer-correct":wrong?"answer-incorrect":""} key={target} disabled={Boolean(done[item.id])} onClick={()=>onPick(item.id,target)}>{correct&&<span className="answer-status">✓ Richtig · </span>}{wrong&&<span className="answer-status">✗ Noch zu prüfen · </span>}{labels[target]??target}</button>})}</fieldset>)}</div>}
function Sorter({title,items,onSolve}:{title:string;items:readonly {id:string;label:string}[];onSolve:(ids:string[])=>void}){const[order,setOrder]=useState(items.map(x=>x.id));const move=(i:number,d:number)=>setOrder(old=>{const n=[...old],j=i+d;if(j<0||j>=n.length)return old;[n[i],n[j]]=[n[j],n[i]];return n});return <div><h2>{title}</h2><TaskInstruction>Bringen Sie alle Karten mit den Pfeiltasten in die Reihenfolge, die den belegten Handlungsverlauf von Ausgangslage bis Folge zeigt.</TaskInstruction><ol className="curve-sorter">{order.map((id,i)=>{const item=items.find(x=>x.id===id)!;return <li key={id}><span>{item.label}</span><span><button aria-label={`${item.label} nach oben`} disabled={!i} onClick={()=>move(i,-1)}>↑</button><button aria-label={`${item.label} nach unten`} disabled={i===order.length-1} onClick={()=>move(i,1)}>↓</button></span></li>})}</ol><button className="primary-action" onClick={()=>onSolve(order)}>Verlauf prüfen</button></div>}
type ChainTask={id:string;impulse:string;reaction:string;effect:string;impulseOptions?:readonly string[];reactionOptions?:readonly string[];effectOptions?:readonly string[]};
function ActionChains({title,tasks,done,onSolve,onFailure}:{title:string;tasks:readonly ChainTask[];done:string[];onSolve:(id:string,a:string,b:string,c:string)=>void;onFailure:(message:string,resolution:string)=>void}){const task=tasks.find(x=>!done.includes(x.id));const[a,setA]=useState(""),[b,setB]=useState(""),[note,setNote]=useState("");if(!task)return <p className="secured-chain">✓ Alle Handlungsketten sind verbunden.</p>;const options=(kind:"impulse"|"reaction"|"effect")=>task[`${kind}Options`]??tasks.map(x=>x[kind]);const resolution=`Richtig ist „${task.impulse} → ${task.reaction} → ${task.effect}“, weil die Reaktion unmittelbar auf den Impuls antwortet und genau diese Veränderung im Handlungsverlauf erzeugt.`;const fail=(message:string)=>{setNote(message);onFailure(message,resolution)};const pickA=(v:string)=>{if(v!==task.impulse){fail(`„${v}“ ist für diese Kette nicht der auslösende Impuls.`);return}setA(v);setNote("Der Impuls ist gesichert. Wählen Sie nun die unmittelbare Reaktion.")};const pickB=(v:string)=>{if(v!==task.reaction){fail(`„${v}“ ist nicht die unmittelbare Reaktion auf „${task.impulse}“.`);return}setB(v);setNote("Die Reaktion passt. Prüfen Sie nun, was sich dadurch verändert.")};return <div><h2>{title}</h2><div className="analysis-chain"><Choice title="1. Impuls / Handlung" options={options("impulse").map(x=>({id:x,label:x}))} onPick={pickA}/>{a&&<Choice title="2. Reaktion" options={options("reaction").map(x=>({id:x,label:x}))} onPick={pickB}/>} {b&&<Choice title="3. Folge / Veränderung" options={options("effect").map(x=>({id:x,label:x}))} onPick={c=>{if(c!==task.effect){fail(`„${c}“ ist nicht die aus dieser Handlung und Reaktion entstehende Veränderung.`);return}onSolve(task.id,a,b,c)}}/>}</div>{note&&<p role="status">{note}</p>}</div>}
function GeneralEvidence({task,onSolve}:{task:(typeof generalEvidenceTasks)[number];onSolve:(a:number,b:number)=>void}){const[evidence,setEvidence]=useState<number|null>(null);return <div><Kicker>Behauptung → Textbeleg → Analyse</Kicker><h2>{task.claim}</h2><Choice title="Welcher Textbeleg passt?" options={task.evidenceOptions.map((label,i)=>({id:String(i),label}))} onPick={id=>setEvidence(Number(id))}/>{evidence!==null&&<Choice title="Was zeigt der Beleg?" options={task.analysisOptions.map((label,i)=>({id:String(i),label}))} onPick={id=>onSolve(evidence,Number(id))}/>}</div>}
function Turning({title,items,onPick}:{title:string;items:readonly {id:string;label:string;before:string;change:string;after:string;judgement:string}[];onPick:(id:string,j:string)=>void}){const[id,setId]=useState("");const item=items.find(x=>x.id===id);return <div><h2>{title}</h2><Choice title="Kandidat wählen" options={items.map(x=>({id:x.id,label:x.label}))} onPick={setId}/>{item&&<div className="turning-review"><p><strong>DAVOR:</strong> {item.before}</p><p><strong>VERÄNDERUNG:</strong> {item.change}</p><p><strong>DANACH:</strong> {item.after}</p><Choice title="Urteil" options={[{id:"turning",label:"Zentraler Wendepunkt"},{id:"escalation",label:"Wichtige Zuspitzung"},{id:"unsupported",label:"Nicht ausreichend als Wendepunkt begründet"}]} onPick={j=>onPick(item.id,j)}/></div>}</div>}
function Goals({s,apply}:{s:Chapter04Session;apply:(r:Result,key?:string,ok?:string,wrong?:string,details?:FailureDetails)=>void}){const task=goals.find(x=>!s.goalAnalyses.includes(x.id));const[evidence,setEvidence]=useState("");if(!task)return <p>✓ Beide Ziele sind mit Beleg und Analyse gesichert.</p>;const goalChosen=s.goalChoices[task.id]!==undefined;return <div><h2>{task.character}: Ziel selbst erschließen</h2>{!goalChosen?<Choice title="Welches Ziel verfolgt die Figur in dieser Situation?" options={task.goalOptions.map((label,i)=>({id:String(i),label}))} onPick={id=>apply(chooseGoal(s,task.id,Number(id)),`goal-choice-${task.id}:${id}`,"✓ Das Ziel ist aus dem Verhalten erschlossen.","Prüfen Sie, was die Figur in dieser Situation erreichen will.")}/>:<><EvidenceChoice title="Welcher Primärtextbeleg stützt dieses Ziel?" ids={task.evidenceOptions} onPick={setEvidence}/>{evidence&&<Choice title="Was zeigt der gewählte Beleg?" options={task.analysisOptions.map((label,i)=>({id:String(i),label}))} onPick={id=>apply(linkGoal(s,task.id,evidence,task.analysisOptions[Number(id)]),`goal-${task.id}:${evidence}:${id}`,"✓ Ziel, konkreter Primärtextbeleg und Analyse passen zusammen.","Beleg und Analyse müssen das zuvor bestimmte Ziel tatsächlich stützen.",{incorrectItems:[`Gewählt wurden der Beleg „${sourceById(evidence)?.text??evidence}“ und die Analyse „${task.analysisOptions[Number(id)]}“.`],resolution:chapter04Resolution(`goal-${task.id}`)})}/>}</>}</div>}
function EvidenceChoice({title,ids,onPick}:{title:string;ids:readonly string[];onPick:(id:string)=>void}){const presented=stablePresentationOrderBy(ids.map((id,sourceIndex)=>({id,sourceIndex})),`chapter04-evidence-${title}`,item=>item.id);return <fieldset className="causal-choice"><legend>{title}</legend>{presented.map(({id,sourceIndex})=>{const source=sourceById(id);return <button data-evidence-id={id} key={id} onClick={()=>onPick(id)}><strong>B{sourceIndex+1}</strong>{source&&<PrimarySourceText record={source} kind={stageDirections.has(id)?"stage_direction":"speech"}/>}</button>})}</fieldset>}
function Relations({s,apply}:{s:Chapter04Session;apply:(r:Result,key?:string,ok?:string,wrong?:string)=>void}){return <div className="relation-checks"><h2>Reihenfolge ist nicht automatisch Kausalität</h2>{chainLinks.filter(x=>!s.chainRelations[`${x.from}:${x.to}`]).map(link=><Choice key={link.from} title={`${chain.find(x=>x.id===link.from)?.label} → ${chain.find(x=>x.id===link.to)?.label}`} options={[{id:"causes",label:"Verursacht die unmittelbare Reaktion"},{id:"contributes",label:"Trägt zur Entwicklung oder Eskalation bei"},{id:"only_later",label:"Folgt nur später; kein belegter Kausalzusammenhang"}]} onPick={t=>apply(setChainRelation(s,link.from,link.to,t),`relation-${link.from}:${t}`,t==="contributes"?"✓ Dieser Schritt verstärkt die Entwicklung, verursacht den späteren Kampf aber nicht allein.":"✓ Die konkrete Ereignisbeziehung ist passend bestimmt.")}/>)}</div>}
function Shakespeare({ids,children}:{ids:string[];children:ReactNode}){return <div className="chapter04-text-layout"><Manuscript ids={ids}/><section className="chapter04-analysis">{children}</section></div>}
const stageDirections=new Set(["c04_tomb_fight","c04_juliet_execution"]);
function Manuscript({ids}:{ids:string[]}){return <details className="chapter04-manuscript" open><summary>Primärtext anzeigen / Text schließen</summary><div>{ids.map((id,index)=>{const source=sourceById(id);return source?<article id={`evidence-${id}`} key={id}><small>B{index+1} · {stageDirections.has(id)?"ORIGINALE BÜHNENANWEISUNG":"ORIGINALTEXT"}</small><PrimarySourceText record={source} kind={stageDirections.has(id)?"stage_direction":"speech"}/></article>:null})}</div></details>}
